Item.method_code:
	var scheduledJobId = this.getID();
	var dataAccessLayer = new DataAccessLayer(CCO.Permissions);
	var businessLogic = new BusinessLogic(dataAccessLayer, getInnovator());
	return businessLogic.DeleteRelatedJobs(scheduledJobId);
}

internal class BusinessLogic
{
	private readonly IDataAccessLayer _dataAccessLayer;
	private readonly Innovator _innovator;

	internal BusinessLogic(IDataAccessLayer dataAccessLayer, Innovator innovator)
	{
		_dataAccessLayer = dataAccessLayer;
		_innovator = innovator;
	}

	public Item DeleteRelatedJobs(string scheduledJobId)
	{
		var jobsDeleteRequest = _innovator.newItem("cjs_Job", "delete");
		jobsDeleteRequest.setAttribute("where", $"template='{scheduledJobId}'");
		return _dataAccessLayer.ApplyAsJobManager(jobsDeleteRequest);
	}
}

internal interface IDataAccessLayer
{
	Item ApplyAsJobManager(Item item);
}

internal class DataAccessLayer : IDataAccessLayer
{
	private readonly Aras.Server.Core.Abstractions.IPermissions _permissions;

	internal DataAccessLayer(Aras.Server.Core.Abstractions.IPermissions permissions)
	{
		_permissions = permissions;
	}

	public Item ApplyAsJobManager(Item item)
	{
		var identity = Aras.Server.Security.Identity.GetByName("cjs_Job Manager");
		using (_permissions.GrantIdentity(identity))
		{
			return item.apply();
		}
	}
